        logEl.innerHTML += '<div style="color:#fca5a5; margin-top:4px; font-weight:700;">↳ push for <code style="color:#fef3c7;">' + p.key + '</code> FAILED: ' + em + '</div>';
        next();
      });
    };
    next();
  };
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminLibraryPublisher"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminLibraryPublisher !== "function") {
      eli.log.event("tool", "admin_library_publisher_fn_missing", {});
      if (typeof showToast === "function") showToast("Admin Library Publisher failed to load", "err");
      return;
    }
    try { window.showAdminLibraryPublisher(); }
    catch (e) {
      eli.log.event("tool", "admin_library_publisher_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  // Library cipher bridge — the v2 globals `_eliGetLibraryCipher` and
  // `_eliEncryptForRepo` are still expected by the published v2 logic.
  // Kernel exposes the underlying functions; thin shims map old names to
  // current paths so showAdminLibraryPublisher.js doesn't need rewriting.
  if (typeof window._eliGetLibraryCipher !== "function") {
    window._eliGetLibraryCipher = function () {
      try { return eli.compat && eli.compat.lsGet ? eli.compat.lsGet("eli_lib_cipher") || "" : ""; }
      catch (e) { return ""; }
    };
  }

  // Display-version bumper: "1.0" → "1.1" → … → "1.9" → "2.0". Used by
  // both the row render and the push pick to auto-increment. Inlined
  // because the v2 global it expects (`window._eliBumpDisplayVersion`)
  // isn't reliably present in v3 installs.
  if (typeof window._eliBumpDisplayVersion !== "function") {
    window._eliBumpDisplayVersion = function (curV) {
      var s = String(curV || "1.0");
      var m = /^(\d+)\.(\d+)$/.exec(s);
      if (!m) { var n = Number(s); return isNaN(n) ? "1.1" : String(n + 1); }
      var major = parseInt(m[1], 10);
      var minor = parseInt(m[2], 10);
      if (minor >= 9) { major++; minor = 0; } else { minor++; }
      return major + "." + minor;
    };
  }

  // HTML escape helper — v2 named it `_ebEsc`. Provide it inline.
  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  // loadFeatureData shim — v2 helper; v3 uses eli.storage.getAll directly.
  // showAdminLibraryPublisher checks `typeof loadFeatureData === "function"`
  // as a guard; provide a thin wrapper so that gate passes + the function
  // delegates to v3 storage.
  if (typeof window.loadFeatureData !== "function") {
    window.loadFeatureData = function (storeName) {
      if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
      return eli.storage.getAll(storeName).then(function (rows) {
        return (rows || []).filter(function (r) {
          return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
        });
      });
    };
  }

  eli.register({
    tile: { app_admin_library_publisher: _show },
    admin_library_publisher: { open: _show },
  });

  eli.log.event("tool", "admin_library_publisher_initialized", {});
}
